var N=20,ROWS=12,BL=' ▁▂▃▄▅▆▇█';
var plot=root.querySelector('.tch-candles-plot');
var hit=root.querySelector('.tch-candles-hit');
var rd=root.querySelector('.tch-candles-rd');
var s=99127;
function rnd(){s=(s*1664525+1013904223)>>>0;return s/4294967296;}
function r2(x){return Math.round(x*100)/100;}
var MON=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
var d=new Date(2025,7,19),bars=[],px=112.86,i,r,b;
for(i=0;i<N;i++){
  do{d=new Date(d.getTime()+864e5);}while(d.getDay()===0||d.getDay()===6);
  var o=r2(px*(1+(rnd()-0.5)*0.005));
  var dr=(rnd()-0.44)*0.030;
  var c=r2(o*(1+dr));
  var w=o*(0.003+rnd()*0.010);
  var h=r2(Math.max(o,c)+w*rnd()),l=r2(Math.min(o,c)-w*rnd());
  h=Math.max(h,o,c);l=Math.min(l,o,c);
  bars.push({o:o,h:h,l:l,c:c,v:Math.round((24+rnd()*18+Math.abs(dr)*900)*10)/10,
    lab:(d.getDate()<10?'0':'')+d.getDate()+' '+MON[d.getMonth()]});
  px=c;
}
var hi=-1e9,lo=1e9,vmax=0;
for(i=0;i<N;i++){if(bars[i].h>hi)hi=bars[i].h;if(bars[i].l<lo)lo=bars[i].l;if(bars[i].v>vmax)vmax=bars[i].v;}
var pad=(hi-lo)*0.05;hi+=pad;lo-=pad;
function rw(p){var t=Math.round((hi-p)/(hi-lo)*(ROWS-1));return t<0?0:(t>ROWS-1?ROWS-1:t);}
function sp(cls,txt){return cls?'<span class="'+cls+'">'+txt+'</span>':txt;}
function emit(cells){var out='',cur=null,buf='',k;
  for(k=0;k<cells.length;k++){if(cells[k][0]!==cur){if(buf)out+=sp(cur,buf);cur=cells[k][0];buf='';}buf+=cells[k][1];}
  if(buf)out+=sp(cur,buf);return out;}
var sel=N-1;
function draw(){
  var out='',cells,lab,k;
  for(r=0;r<ROWS;r++){
    cells=[];
    if(r%3===0){lab=(hi-(hi-lo)*r/(ROWS-1)).toFixed(2);while(lab.length<6)lab=' '+lab;}else lab='      ';
    for(k=0;k<6;k++)cells.push(['ax',lab.charAt(k)]);
    cells.push(['ax','│']);
    for(i=0;i<N;i++){
      b=bars[i];var up=b.c>=b.o,cc='gr',ch=' ';
      var rt=rw(Math.max(b.o,b.c)),rb=rw(Math.min(b.o,b.c)),rh=rw(b.h),rl=rw(b.l);
      if(r>=rt&&r<=rb){ch=up?'█':'▓';cc=up?'u':'d';}
      else if(r>=rh&&r<=rl){ch='│';cc=up?'u':'d';}
      else if(r%3===0){ch='·';}
      cells.push([cc+(i===sel?' sl':''),ch]);
      cells.push([i===sel?'sl':'',' ']);
    }
    out+='<div>'+emit(cells)+'</div>';
  }
  cells=[['ax','      '],['ax','├']];
  for(i=0;i<N;i++)cells.push(['ax','──']);
  out+='<div>'+emit(cells)+'</div>';
  cells=[['ax','   VOL'],['ax','│']];
  for(i=0;i<N;i++){
    b=bars[i];var ix=Math.max(1,Math.round(b.v/vmax*8));
    cells.push([(b.c>=b.o?'u':'d')+(i===sel?' sl':''),BL.charAt(ix)]);
    cells.push([i===sel?'sl':'',' ']);
  }
  out+='<div>'+emit(cells)+'</div>';
  plot.innerHTML=out;
  var h='<span class="ax">       </span>';
  for(i=0;i<N;i++)h+='<span data-i="'+i+'" class="'+(i===sel?'mk':'')+'">'+(i===sel?'▲ ':'  ')+'</span>';
  hit.innerHTML=h;
}
function rdraw(){
  var bb=bars[sel],pc=sel?bars[sel-1].c:r2(bars[0].o-0.42);
  var ch=r2(bb.c-pc),pct=ch/pc*100,k=ch>=0?'u':'d',sg=ch>=0?'+':'';
  var f=[['DATE',bb.lab,''],['O',bb.o.toFixed(2),''],['H',bb.h.toFixed(2),''],['L',bb.l.toFixed(2),''],
         ['C',bb.c.toFixed(2),k],['CHG',sg+ch.toFixed(2),k],['%',sg+pct.toFixed(2),k],['VOL',bb.v.toFixed(1)+'M','']];
  rd.innerHTML=f.map(function(x){return '<span><i>'+x[0]+'</i>'+sp(x[2],x[1])+'</span>';}).join('');
  rd.classList.remove('fl');void rd.offsetWidth;rd.classList.add('fl');
}
hit.addEventListener('click',function(e){
  var t=e.target&&e.target.getAttribute?e.target.getAttribute('data-i'):null;
  if(t===null)return;sel=+t;draw();rdraw();
});
plot.addEventListener('keydown',function(e){
  if(e.key==='ArrowLeft'||e.key==='ArrowRight'){
    sel=Math.max(0,Math.min(N-1,sel+(e.key==='ArrowRight'?1:-1)));
    e.preventDefault();draw();rdraw();
  }
});
draw();rdraw();

