var BL='▁▂▃▄▅▆▇█',WIN=18;
var bd=root.querySelector('.tch-sparkrow-bd'),clk=root.querySelector('.tch-sparkrow-clk');
var s=771931;
function rnd(){s=(s*1664525+1013904223)>>>0;return s/4294967296;}
function g(){return rnd()+rnd()+rnd()+rnd()+rnd()+rnd()-3;}
var INS=[
 {s:'ESZ5',p:5842.25,pc:5818.50,d:2,k:0.25,v:0.9,u:'%'},
 {s:'NQZ5',p:20418.50,pc:20289.25,d:2,k:0.25,v:1.3,u:'%'},
 {s:'CLX5',p:78.42,pc:79.16,d:2,k:0.01,v:1.8,u:'%'},
 {s:'GCZ5',p:2648.30,pc:2641.90,d:2,k:0.10,v:0.8,u:'%'},
 {s:'EUR=',p:1.08425,pc:1.08610,d:5,k:0.00005,v:0.4,u:'%'},
 {s:'US10Y',p:4.281,pc:4.243,d:3,k:0.001,v:0,u:'bp'},
 {s:'BTC=',p:63418,pc:62740,d:0,k:1,v:2.4,u:'%'},
 {s:'VIX',p:14.62,pc:15.08,d:2,k:0.01,v:4.0,u:'%'}
];
function snap(o,x){return Math.round(x/o.k)*o.k;}
function step(o){return o.u==='bp'?g()*0.0035:g()*o.p*o.v/100*0.22;}
INS.forEach(function(o){
  var w=[],v=o.pc,i;
  for(i=0;i<WIN;i++){v+=step(o);w.push(v);}
  var adj=o.p-w[WIN-1];
  for(i=0;i<WIN;i++)w[i]=snap(o,w[i]+adj*(i+1)/WIN);
  o.w=w;o.prev=o.p;
});
function fmt(o,x){return x.toFixed(o.d).replace(/\B(?=(\d{3})+(?!\d))/g,x<1000?'':',');}
function chg(o){
  if(o.u==='bp'){var b=(o.p-o.pc)*100;return (b>=0?'+':'')+b.toFixed(1)+'bp';}
  var p=(o.p-o.pc)/o.pc*100;return (p>=0?'+':'')+p.toFixed(2)+'%';
}
function spark(o){
  var w=o.w,mn=1e18,mx=-1e18,i,out='',up=o.p>=o.pc;
  for(i=0;i<WIN;i++){if(w[i]<mn)mn=w[i];if(w[i]>mx)mx=w[i];}
  var rg=mx-mn||1,cls=up?'up':'dn';
  for(i=0;i<WIN-1;i++)out+=BL.charAt(Math.round((w[i]-mn)/rg*7));
  return '<span class="'+cls+'">'+out+'</span><span class="hl">'+BL.charAt(Math.round((w[WIN-1]-mn)/rg*7))+'</span>';
}
function draw(){
  bd.innerHTML=INS.map(function(o){
    var up=o.p>=o.pc,f=o.p>o.prev?' fu':(o.p<o.prev?' fd':'');
    return '<div class="r"><span class="sym">'+o.s+'</span>'+
      '<span class="'+(up?'up':'dn')+f+'">'+fmt(o,o.p)+'</span>'+
      '<span class="'+(up?'up':'dn')+'">'+(up?'▲':'▼')+chg(o)+'</span>'+
      '<span class="spk">'+spark(o)+'</span></div>';
  }).join('');
}
var secs=13*3600+45*60;
function clock(){
  var h=Math.floor(secs/3600),m=Math.floor(secs/60)%60,x=secs%60;
  clk.textContent=(h<10?'0':'')+h+':'+(m<10?'0':'')+m+':'+(x<10?'0':'')+x;
}
draw();clock();
var t=setInterval(function(){
  if(!root.isConnected){clearInterval(t);return;}
  secs+=5;
  INS.forEach(function(o){
    o.prev=o.p;
    var n=snap(o,o.p+step(o));
    o.p=n;o.w.push(n);o.w.shift();
  });
  draw();clock();
},900);

