var SEC=[['TECHNOLOGY',26.4,-8.2,1.18],['FINANCIALS',14.8,-3.6,1.05],['INDUSTRIALS',9.6,-2.8,1.09],
 ['HEALTH CARE',11.2,-5.4,0.82],['CONS DISCR',8.8,-4.2,1.14],['CONS STAPLE',5.2,-1.4,0.61],
 ['UTILITIES',2.2,-0.9,0.48],['REAL ESTATE',1.2,-3.4,0.88],['MATERIALS',3.1,-6.8,0.96],
 ['ENERGY',4.2,-9.6,0.74]];
var bd=root.querySelector('.tch-barh-bd'),dt=root.querySelector('.tch-barh-dt'),ft=root.querySelector('.tch-barh-ft');
var HW=11,sel=0,i;
function r1(x){return Math.round(x*10)/10;}
var rows=SEC.map(function(x){return {n:x[0],l:x[1],s:x[2],b:x[3],net:r1(x[1]+x[2]),gr:r1(x[1]-x[2])};});
var mx=0;rows.forEach(function(r){if(Math.abs(r.net)>mx)mx=Math.abs(r.net);});
function rep(c,n){var o='';while(n-->0)o+=c;return o;}
function padL(t,n){while(t.length<n)t=' '+t;return t;}
function padR(t,n){while(t.length<n)t=t+' ';return t;}
function bar(v){
  var n=Math.abs(v)/mx*HW,f=Math.floor(n),h=(n-f)>=0.5,L,R;
  if(f>HW){f=HW;h=false;}
  if(v>=0){R=rep('█',f)+(h?'▌':'');if(!R&&v>0.001)R='▏';L=rep(' ',HW);R=padR(R,HW);}
  else{var lb=(h?'▐':'')+rep('█',f);if(!lb&&v<-0.001)lb='▕';L=padL(lb,HW);R=rep(' ',HW);}
  return [L,R];
}
function draw(){
  bd.innerHTML=rows.map(function(r,k){
    var b=bar(r.net),c=r.net>=0?'u':'d';
    return '<div class="r'+(k===sel?' on':'')+'" data-i="'+k+'" role="option" aria-selected="'+(k===sel?'true':'false')+'">'+
      '<span class="nm">'+padR(r.n,12)+'</span>'+
      '<span class="'+c+'">'+padL((r.net>=0?'+':'')+r.net.toFixed(1),6)+' </span>'+
      '<span class="d">'+b[0]+'</span><span class="ax">│</span><span class="u">'+b[1]+'</span>'+
      '<span class="ax">'+padL(r.gr.toFixed(1),7)+'</span></div>';
  }).join('');
  var r=rows[sel],ba=r1(r.net*r.b);
  dt.innerHTML='<b>'+r.n+'</b><span><i>L </i>+'+r.l.toFixed(1)+'</span><span><i>S </i>'+r.s.toFixed(1)+
    '</span><span><i>NET </i>'+(r.net>=0?'+':'')+r.net.toFixed(1)+'</span><span><i>GR </i>'+r.gr.toFixed(1)+
    '</span><span><i>β </i>'+r.b.toFixed(2)+'</span><span><i>β-ADJ </i>'+(ba>=0?'+':'')+ba.toFixed(1)+'</span>';
}
var L=0,S=0,BA=0;
rows.forEach(function(r){L+=r.l;S+=r.s;BA+=r.net*r.b;});
L=r1(L);S=r1(S);BA=r1(BA);
ft.innerHTML='<span><i>LONG </i>+'+L.toFixed(1)+'</span><span><i>SHORT </i>'+S.toFixed(1)+
 '</span><span><i>GROSS </i>'+r1(L-S).toFixed(1)+'</span><span><i>NET </i>+'+r1(L+S).toFixed(1)+
 '</span><span><i>β-ADJ NET </i>+'+BA.toFixed(1)+'</span><span><i>SCALE </i>±'+mx.toFixed(1)+'</span>';
bd.addEventListener('click',function(e){
  var n=e.target,k=null;
  while(n&&n!==bd){if(n.getAttribute&&n.getAttribute('data-i')!==null){k=n.getAttribute('data-i');break;}n=n.parentNode;}
  if(k===null)return;sel=+k;draw();
});
bd.addEventListener('keydown',function(e){
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){
    sel=Math.max(0,Math.min(rows.length-1,sel+(e.key==='ArrowDown'?1:-1)));
    e.preventDefault();draw();
  }
});
draw();

