var TK=['NVDA','AAPL','MSFT','AMZN','META','TSLA','JPM ','XOM '];
var BASE=[122.65,224.18,418.42,186.30,563.10,241.85,214.60,113.42];
var VOL=[2.6,1.4,1.3,1.8,2.0,3.2,1.1,1.3];
var COLS=12,MON=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
var grid=root.querySelector('.tch-heat-grid'),rd=root.querySelector('.tch-heat-rd'),lg=root.querySelector('.tch-heat-lg');
var s=451207;
function rnd(){s=(s*1664525+1013904223)>>>0;return s/4294967296;}
function g(){return rnd()+rnd()+rnd()+rnd()+rnd()+rnd()-3;}
var d=new Date(2025,8,1),dates=[],i,j;
while(dates.length<COLS){if(d.getDay()!==0&&d.getDay()!==6)dates.push((d.getDate()<10?'0':'')+d.getDate()+' '+MON[d.getMonth()]);d=new Date(d.getTime()+864e5);}
var R=[],CL=[];
for(i=0;i<TK.length;i++){
  R.push([]);CL.push([]);var acc=1;
  for(j=0;j<COLS;j++){var r=g()*VOL[i]*0.62;R[i].push(Math.round(r*100)/100);acc*=1+r/100;}
  var base=BASE[i]/acc;
  var run=base;
  for(j=0;j<COLS;j++){run=run*(1+R[i][j]/100);CL[i].push(run);}
