var TICK=0.25,N=7,BW=9;
var bd=root.querySelector('.tch-ladder-bd'),ft=root.querySelector('.tch-ladder-ft'),lastEl=root.querySelector('.tch-ladder-last');
var s=330441;
function rnd(){s=(s*1664525+1013904223)>>>0;return s/4294967296;}
function rep(c,n){var o='';while(n-->0)o+=c;return o;}
function padL(t,n){while(t.length<n)t=' '+t;return t;}
function padR(t,n){while(t.length<n)t=t+' ';return t;}
function comma(n){return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
var bestBid=5842.25,i;
var bids=[],asks=[];
function tgt(k){return 90+k*k*7;}
function newq(k){return Math.round(tgt(k)*(0.78+rnd()*0.44));}
for(i=0;i<N;i++){bids.push(newq(i));asks.push(newq(i));}
var last={p:bestBid+TICK,side:1,q:12},age=0;
function draw(){
  var mx=1,k;
  for(k=0;k<N;k++){if(bids[k]>mx)mx=bids[k];if(asks[k]>mx)mx=asks[k];}
  var out='';
  for(k=N-1;k>=0;k--){
    var p=bestBid+TICK*(k+1),q=asks[k];
    var n=Math.round(q/mx*BW);
    var hit=(Math.abs(last.p-p)<1e-9&&age<3);
    out+='<div class="'+(hit?'fl':'')+'">'+
      '<span class="mk">'+(hit?'◀':' ')+' </span>'+
      '<span class="ax">'+rep(' ',BW)+'      </span>'+
      '<span class="'+(k===0?'px tc':'px')+'">'+padL(p.toFixed(2),8)+' </span>'+
      '<span class="a">'+padL(comma(q),5)+' </span>'+
      '<span class="a">'+padR(rep('█',n),BW)+'</span></div>';
  }
  out+='<div><span class="ax">'+rep('─',BW+12)+'┼'+rep('─',BW+10)+'</span></div>';
  for(k=0;k<N;k++){
    var pb=bestBid-TICK*k,qb=bids[k];
    var nb=Math.round(qb/mx*BW);
    var hitb=(Math.abs(last.p-pb)<1e-9&&age<3);
    out+='<div class="'+(hitb?'fl':'')+'">'+
      '<span class="mk">'+(hitb?'◀':' ')+' </span>'+
      '<span class="b">'+padL(rep('█',nb),BW)+'</span>'+
      '<span class="b">'+padL(comma(qb),5)+' </span>'+
      '<span class="'+(k===0?'px tc':'px')+'">'+padL(pb.toFixed(2),8)+' </span>'+
      '<span class="ax">'+rep(' ',BW+6)+'</span></div>';
  }
  bd.innerHTML=out;
  var tb=0,ta=0;
  for(k=0;k<N;k++){tb+=bids[k];ta+=asks[k];}
  var imb=(tb-ta)/(tb+ta)*100,mid=bestBid+TICK/2;
  ft.innerHTML='<span><i>MID </i>'+mid.toFixed(3)+'</span>'+
    '<span><i>SPRD </i>1t '+(TICK/mid*1e4).toFixed(2)+'bp</span>'+
    '<span><i>BID </i>'+comma(tb)+'</span><span><i>ASK </i>'+comma(ta)+'</span>'+
    '<span><i>IMB </i>'+(imb>=0?'+':'')+imb.toFixed(1)+'% '+(imb>=0?'BID':'ASK')+'</span>'+
    '<span><i>LVL </i>'+N+'×'+N+'</span>';
  lastEl.innerHTML='LAST '+last.p.toFixed(2)+' <span class="'+(last.side>0?'b':'a')+'">'+
    (last.side>0?'▲':'▼')+' '+last.q+'</span>';
}
draw();
var t=setInterval(function(){
  if(!root.isConnected){clearInterval(t);return;}
  var k;age++;
  for(k=0;k<N;k++){
    bids[k]=Math.max(8,Math.round(bids[k]+(tgt(k)-bids[k])*0.20+(rnd()-0.5)*tgt(k)*0.20));
    asks[k]=Math.max(8,Math.round(asks[k]+(tgt(k)-asks[k])*0.20+(rnd()-0.5)*tgt(k)*0.20));
  }
  if(rnd()<0.55){
    var tb=0,ta=0;
    for(k=0;k<N;k++){tb+=bids[k];ta+=asks[k];}
    var buy=rnd()<0.5+(tb-ta)/(tb+ta)*0.35;
    var q=Math.round(3+rnd()*32);
    last={p:buy?bestBid+TICK:bestBid,side:buy?1:-1,q:q};age=0;
    if(buy){asks[0]-=q;if(asks[0]<10){bestBid+=TICK;asks.shift();asks.push(newq(N-1));bids.pop();bids.unshift(newq(0));}}
    else{bids[0]-=q;if(bids[0]<10){bestBid-=TICK;bids.shift();bids.push(newq(N-1));asks.pop();asks.unshift(newq(0));}}
  }
  draw();
},800);

