var bd=root.querySelector('.tch-tape-bd'),st=root.querySelector('.tch-tape-st'),ft=root.querySelector('.tch-tape-ft');
var VEN=['XNAS','ARCX','BATS','EDGX','XBOS','TRF '];
var s=610337;
function rnd(){s=(s*1664525+1013904223)>>>0;return s/4294967296;}
function rep(c,n){var o='';while(n-->0)o+=c;return o;}
function comma(n){return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
var bid=122.63,ask=122.65,cumQ=1243000,cumPV=1243000*122.58,secs=14*3600+31*60+52,rows=[],last=122.65;
function clock(){var h=Math.floor(secs/3600),m=Math.floor(secs/60)%60,x=secs%60;
  return (h<10?'0':'')+h+':'+(m<10?'0':'')+m+':'+(x<10?'0':'')+x;}
function print1(){
  if(rnd()<0.30){
    var up=rnd()<0.5;bid=Math.round((bid+(up?0.01:-0.01))*100)/100;ask=Math.round((bid+0.02)*100)/100;
  }
  var u=rnd(),side=u<0.46?1:(u<0.92?-1:0);
  var q=rnd()<0.07?Math.round(70+rnd()*60)*100:Math.round(1+rnd()*24)*100;
  var p=side>0?ask:(side<0?bid:Math.round((bid+0.01)*100)/100);
  var ven=side===0?'TRF ':VEN[Math.floor(rnd()*5)];
  secs+=1+Math.floor(rnd()*4);
  cumQ+=q;cumPV+=q*p;last=p;
  rows.unshift({t:clock(),p:p,q:q,s:side,v:ven,n:true});
  if(rows.length>11)rows.pop();
}
function bar(q){var n=Math.round(Math.log(q/100)/Math.log(120)*7);return rep('█',Math.max(1,Math.min(7,n)));}
function draw(){
  bd.innerHTML=rows.map(function(r){
    var c=r.s>0?'b':(r.s<0?'a':'m'),g=r.s>0?'▲':(r.s<0?'▼':'◆'),lb=r.s>0?'BUY':(r.s<0?'SELL':'MID');
    return '<div class="r'+(r.n?' new':'')+'"><span class="t">'+r.t+'</span>'+
      '<span class="'+c+'">'+r.p.toFixed(2)+'</span>'+
      '<span>'+comma(r.q)+'</span>'+
      '<span class="'+c+'">'+g+' '+lb+'</span>'+
      '<span class="v">'+r.v+'</span>'+
      '<span class="'+c+'">'+bar(r.q)+(r.q>=10000?'<b class="blk">BLK</b>':'')+'</span></div>';
  }).join('');
  rows.forEach(function(r){r.n=false;});
  var vw=cumPV/cumQ,bp=(last-vw)/vw*1e4;
  st.innerHTML='LAST <span class="'+(last>=vw?'b':'a')+'">'+last.toFixed(2)+'</span> '+
    (bp>=0?'+':'')+bp.toFixed(1)+'bp vs VWAP';
  ft.innerHTML='<span><i>VWAP </i>'+vw.toFixed(3)+'</span>'+
    '<span><i>CUM </i>'+(cumQ/1e6).toFixed(2)+'M</span>'+
    '<span><i>BID </i>'+bid.toFixed(2)+'</span><span><i>ASK </i>'+ask.toFixed(2)+'</span>'+
    '<span><i>SPRD </i>'+((ask-bid)/((ask+bid)/2)*1e4).toFixed(1)+'bp</span>';
}
for(var i=0;i<11;i++)print1();
rows.forEach(function(r){r.n=false;});
draw();
var t=setInterval(function(){
  if(!root.isConnected){clearInterval(t);return;}
  print1();draw();
},700);

