var NB=21,BW=0.35,H=10,PART='▁▂▃▄▅▆▇';
var plot=root.querySelector('.tch-hist-plot'),st=root.querySelector('.tch-hist-st');
var s=386;
function rnd(){s=(s*1664525+1013904223)>>>0;return s/4294967296;}
function nz(){var u=1-rnd(),v=rnd();return Math.sqrt(-2*Math.log(u))*Math.cos(6.283185307*v);}
var R=[],i,j,n=250;
for(i=0;i<n;i++){
  var r=0.135+0.98*nz();
  if(rnd()<0.10)r-=1.05*Math.abs(nz());
  R.push(Math.round(r*1000)/1000);
}
var mean=0;for(i=0;i<n;i++)mean+=R[i];mean/=n;
var m2=0,m3=0,m4=0;
for(i=0;i<n;i++){var dv=R[i]-mean;m2+=dv*dv;m3+=dv*dv*dv;m4+=dv*dv*dv*dv;}
m2/=n;m3/=n;m4/=n;
var sd=Math.sqrt(m2),skew=m3/Math.pow(sd,3),kurt=m4/(m2*m2);
var srt=R.slice().sort(function(a,b){return a-b;});
var k5=Math.floor(n*0.05),var95=srt[k5],cvar=0;
for(i=0;i<=k5;i++)cvar+=srt[i];cvar/=(k5+1);
var hits=0;for(i=0;i<n;i++)if(R[i]>0)hits++;
var cnt=[],mx=0;
for(i=0;i<NB;i++)cnt.push(0);
for(i=0;i<n;i++){var b=Math.round(R[i]/BW)+10;b=b<0?0:(b>NB-1?NB-1:b);cnt[b]++;}
for(i=0;i<NB;i++)if(cnt[i]>mx)mx=cnt[i];
function erf(x){var t=1/(1+0.3275911*Math.abs(x));
  var y=1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-0.284496736)*t+0.254829592)*t*Math.exp(-x*x);
  return x>=0?y:-y;}
function cdf(x){return 0.5*(1+erf((x-mean)/(sd*Math.SQRT2)));}
var fit=[];
for(i=0;i<NB;i++){var lo=(i-10)*BW-BW/2,hi2=(i-10)*BW+BW/2;fit.push(n*(cdf(hi2)-cdf(lo)));}
function rep(c,k){var o='';while(k-->0)o+=c;return o;}
function padL(t,k){while(t.length<k)t=' '+t;return t;}
function cls(i){return i<10?'d':(i>10?'u':'z');}
var out='',line,ht,fh,part,ch,c;
for(var r=0;r<H;r++){
  var lvl=H-r;
  if(r===0)line='<span class="ax">'+padL(String(mx),4)+'│</span>';
  else if(r===Math.floor(H/2))line='<span class="ax">'+padL(String(Math.round(mx/2)),4)+'│</span>';
  else line='<span class="ax">    │</span>';
  for(i=0;i<NB;i++){
    ht=cnt[i]/mx*H;fh=fit[i]/mx*H;
    if(ht>=lvl){line+='<span class="'+cls(i)+'">██</span>';}
    else if(ht>lvl-1){part=Math.round((ht-(lvl-1))*7);ch=PART.charAt(Math.max(0,Math.min(6,part-1)));
      line+='<span class="'+cls(i)+'">'+ch+ch+'</span>';}
    else if(fh>lvl-1&&fh<=lvl){line+='<span class="fit">··</span>';}
    else line+='  ';
  }
  out+='<div>'+line+'</div>';
}
out+='<div><span class="ax">   0└'+rep('─',NB*2)+'</span></div>';
var lab=[[0,'-3.5'],[5,'-1.8'],[10,'0.0'],[15,'+1.8'],[20,'+3.5']],row=[],t;
for(i=0;i<NB*2+5;i++)row.push(' ');
for(i=0;i<lab.length;i++){
  t=lab[i][1];var st0=5+lab[i][0]*2-Math.floor(t.length/2);
  for(j=0;j<t.length;j++)if(st0+j>=0&&st0+j<row.length)row[st0+j]=t.charAt(j);
}
out+='<div><span class="ax">'+row.join('')+'</span></div>';
function clampb(x){return x<0?0:(x>NB-1?NB-1:x);}
var mb=clampb(Math.round(mean/BW)+10),vb=clampb(Math.round(var95/BW)+10);
for(i=0;i<row.length;i++)row[i]=' ';
row[5+mb*2]='μ';row[5+vb*2]='V';
out+='<div><span class="mk">'+row.join('')+'</span></div>';
plot.innerHTML=out;
var F=[['MEAN',(mean>=0?'+':'')+mean.toFixed(3)+'%'],['STDEV',sd.toFixed(2)+'%'],
 ['ANN σ',(sd*Math.sqrt(252)).toFixed(1)+'%'],['SKEW',(skew>=0?'+':'')+skew.toFixed(2)],
 ['KURT',kurt.toFixed(2)],['VaR95',var95.toFixed(2)+'%'],['CVaR95',cvar.toFixed(2)+'%'],
 ['HIT RATE',(hits/n*100).toFixed(1)+'%']];
st.innerHTML=F.map(function(x){
  var neg=x[1].charAt(0)==='-';
  return '<span><i>'+x[0]+'</i><b class="'+(neg?'d':'')+'">'+x[1]+'</b></span>';}).join('');

