.tch-scatter .on{color:#0A0C12;background:#FFB020}
.tch-scatter-rd{display:flex;flex-wrap:wrap;gap:2px 9px;padding:3px 6px;border-top:1px solid #161C27;color:#8FA0B8}
.tch-scatter-rd b{color:#FFB020;font-weight:600}
.tch-scatter-rd i{color:#39445A;font-style:normal}
.tch-scatter-ft{display:flex;justify-content:space-between;gap:8px;padding:3px 6px;border-top:1px solid #161C27;color:#3E4A5C}
@media (prefers-reduced-motion:reduce){
.tch-scatter-plot .c{transition:none}
}

js:
var P=[['NVDA',1.62,38.4,42.1,8.0],['MSFT',0.94,21.2,14.6,9.0],['AAPL',1.06,23.8,9.2,8.4],
['AMZN',1.18,27.4,18.7,6.5],['META',1.24,30.1,23.5,5.6],['GOOGL',1.08,25.3,11.4,6.0],
['AVGO',1.34,33.0,27.8,4.7],['JPM',0.98,19.6,12.9,5.0],['XOM',0.62,18.2,-3.4,3.6],
['CVX',0.58,17.4,-5.8,2.7],['JNJ',0.48,13.1,2.6,3.2],['PG',0.42,12.4,4.1,3.0],
['KO',0.46,11.8,6.3,2.4],['PEP',0.44,13.6,-1.9,2.2],['UNH',0.66,22.9,-8.4,2.6],
['LLY',0.72,26.7,31.2,4.6],['COST',0.79,18.9,16.8,3.4],['HD',1.02,20.4,7.5,3.1],
['CAT',1.12,24.1,19.3,2.9],['TSLA',1.88,46.2,-11.6,3.8],['NFLX',1.28,31.5,25.4,3.3],
['TLT',0.14,14.8,-2.1,6.0]];
var RF=4.30,W=32,H=12,XMAX=2.0,YHI=45,YLO=-20;
var plot=root.querySelector('.tch-scatter-plot'),rd=root.querySelector('.tch-scatter-rd'),agg=root.querySelector('.tch-scatter-agg');
var ord=P.map(function(x,i){return i;}).sort(function(a,b){return P[a][1]-P[b][1];});
var sel=ord[ord.length-1],i,j,k;
function cx(b){var c=Math.round(b/XMAX*(W-1));return c<0?0:(c>W-1?W-1:c);}
function cy(r){var v=Math.round((YHI-r)/(YHI-YLO)*(H-1));return v<0?0:(v>H-1?H-1:v);}
var sx=0,sy=0,sxx=0,sxy=0,syy=0,sw=0,pb=0,pr=0;
for(i=0;i<P.length;i++){
  sx+=P[i][1];sy+=P[i][3];sxx+=P[i][1]*P[i][1];sxy+=P[i][1]*P[i][3];syy+=P[i][3]*P[i][3];
  sw+=P[i][4];pb+=P[i][4]*P[i][1];pr+=P[i][4]*P[i][3];
}
var nP=P.length,den=nP*sxx-sx*sx,slope=(nP*sxy-sx*sy)/den,icpt=(sy-slope*sx)/nP;
var rr=(nP*sxy-sx*sy)/Math.sqrt(den*(nP*syy-sy*sy)),r2=rr*rr;
agg.textContent='PORT β '+(pb/sw).toFixed(2)+' · WTD YTD '+(pr/sw>=0?'+':'')+(pr/sw).toFixed(1)+'%';
root.querySelector('.tch-scatter-r2').innerHTML='<i class="tch-scatter-fit">··</i> OLS SLOPE '+
  (slope>=0?'+':'')+slope.toFixed(1)+' · R² '+r2.toFixed(2);
function rep(c,n){var o='';while(n-->0)o+=c;return o;}
var TICKS=[[40,'+40'],[20,'+20'],[0,'  0'],[-20,'-20']];
function draw(){
  var cells=[],r;
  for(r=0;r<H;r++){cells.push([]);for(j=0;j<W;j++)cells[r].push([]);}
  for(i=0;i<P.length;i++)cells[cy(P[i][3])][cx(P[i][1])].push(i);
  var z=cy(0),one=cx(1.0),out='';
  for(r=0;r<H;r++){
    var lab='   ';
    for(k=0;k<TICKS.length;k++)if(cy(TICKS[k][0])===r)lab=TICKS[k][1];
    var line='<span class="ax">'+lab+'│</span>';
    for(j=0;j<W;j++){
      var pts=cells[r][j];
      if(pts.length){
        var isSel=pts.indexOf(sel)>=0;
        var ch=pts.length>1?String(Math.min(9,pts.length)):'•';
        var c=isSel?'on':(pts.length>1?'mu':(P[pts[0]][3]>=0?'u':'d'));
        line+='<span class="c '+c+'" data-i="'+pts[0]+'">'+ch+'</span>';
      } else {
        var fy=icpt+slope*(j/(W-1)*XMAX);
        if(cy(fy)===r)line+='<span class="fit">·</span>';
        else if(r===z)line+='<span class="gl">─</span>';
        else if(j===one)line+='<span class="gl">┊</span>';
        else line+=' ';
      }
    }
    out+='<div>'+line+'</div>';
  }
  out+='<div><span class="ax">   └'+rep('─',W)+'</span></div>';
  var row=[];for(j=0;j<W+4;j++)row.push(' ');
  var XT=[[0,'0.0'],[0.5,'0.5'],[1.0,'1.0'],[1.5,'1.5'],[2.0,'2.0']];
  for(k=0;k<XT.length;k++){
    var t=XT[k][1],st0=4+cx(XT[k][0])-1;
    if(st0+t.length>row.length)st0=row.length-t.length;
    for(j=0;j<t.length;j++)if(st0+j>=0&&st0+j<row.length)row[st0+j]=t.charAt(j);
  }
  out+='<div><span class="ax">'+row.join('')+'  β</span></div>';
  plot.innerHTML=out;
  var p=P[sel],sh=(p[3]-RF)/p[2];
  rd.innerHTML='<b>'+p[0]+'</b><span><i>β </i>'+p[1].toFixed(2)+'</span>'+
    '<span><i>σ </i>'+p[2].toFixed(1)+'%</span>'+
    '<span><i>YTD </i>'+(p[3]>=0?'+':'')+p[3].toFixed(1)+'%</span>'+
    '<span><i>SHRP </i>'+sh.toFixed(2)+'</span>'+
    '<span><i>W </i>'+p[4].toFixed(1)+'%</span>';
}
plot.addEventListener('click',function(e){
  var n=e.target;
  if(!n||!n.getAttribute||n.getAttribute('data-i')===null)return;
  sel=+n.getAttribute('data-i');draw();
});
plot.addEventListener('keydown',function(e){
  if(e.key==='ArrowUp'||e.key==='ArrowDown'){
    var at=ord.indexOf(sel);
    at=Math.max(0,Math.min(ord.length-1,at+(e.key==='ArrowUp'?1:-1)));
    sel=ord[at];e.preventDefault();draw();
  }
});
draw();
